begin;
create function pg_temp.assert_true(value boolean, message text) returns void language plpgsql as $$ begin if value is distinct from true then raise exception 'Assertion failed: %',message; end if; end $$;
insert into auth.users(id) values ('f0000000-0000-4000-8000-000000000001'),('f0000000-0000-4000-8000-000000000002'),('f0000000-0000-4000-8000-000000000003');
select set_config('request.jwt.claims','{"sub":"f0000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select set_config('ambientis_test.org',public.bootstrap_organization('Synthetic rollback consultancy')::text,true);
select pg_temp.assert_true(public.bootstrap_organization('Retry')::text=current_setting('ambientis_test.org'),'idempotent bootstrap');
insert into public.companies(id,organization_id,name,sector) values ('f1000000-0000-4000-8000-000000000001',current_setting('ambientis_test.org')::uuid,'Synthetic company A','gases'),('f1000000-0000-4000-8000-000000000002',current_setting('ambientis_test.org')::uuid,'Synthetic company B','hospital');
insert into public.facilities(id,organization_id,company_id,name,sector,state,city) values('f2000000-0000-4000-8000-000000000001',current_setting('ambientis_test.org')::uuid,'f1000000-0000-4000-8000-000000000001','Unit A','gases','GO','Goiânia'),('f2000000-0000-4000-8000-000000000002',current_setting('ambientis_test.org')::uuid,'f1000000-0000-4000-8000-000000000002','Unit B','hospital','DF','Brasília');
insert into public.processes(id,organization_id,facility_id,title,reporting_period) values ('f3000000-0000-4000-8000-000000000001',current_setting('ambientis_test.org')::uuid,'f2000000-0000-4000-8000-000000000001','Synthetic process','2026');
insert into public.requirements(id,organization_id,facility_id,process_id,title,shared_with_client) values ('f4000000-0000-4000-8000-000000000001',current_setting('ambientis_test.org')::uuid,'f2000000-0000-4000-8000-000000000001','f3000000-0000-4000-8000-000000000001','Shared requirement',true),('f4000000-0000-4000-8000-000000000002',current_setting('ambientis_test.org')::uuid,'f2000000-0000-4000-8000-000000000001','f3000000-0000-4000-8000-000000000001','Internal requirement',false);
insert into public.document_requests(organization_id,facility_id,process_id,requirement_id,message,status) values(current_setting('ambientis_test.org')::uuid,'f2000000-0000-4000-8000-000000000001','f3000000-0000-4000-8000-000000000001','f4000000-0000-4000-8000-000000000001','Shared request','sent'),(current_setting('ambientis_test.org')::uuid,'f2000000-0000-4000-8000-000000000001','f3000000-0000-4000-8000-000000000001','f4000000-0000-4000-8000-000000000001','Draft request','draft');
reset role;
insert into public.organization_members values(current_setting('ambientis_test.org')::uuid,'f0000000-0000-4000-8000-000000000003','client',true);
insert into public.facility_access values(current_setting('ambientis_test.org')::uuid,'f2000000-0000-4000-8000-000000000001','f0000000-0000-4000-8000-000000000003');
select set_config('request.jwt.claims','{"sub":"f0000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
set local role authenticated;
select pg_temp.assert_true((select count(*)=1 from public.companies),'same-consultancy client isolation');
select pg_temp.assert_true((select count(*)=1 from public.facilities),'facility scope');
select pg_temp.assert_true((select count(*)=1 from public.requirements),'internal requirement hidden');
select pg_temp.assert_true((select count(*)=1 from public.document_requests),'draft request hidden');
select pg_temp.assert_true((select count(*)=0 from public.audit_events),'internal audit hidden');
do $$ begin begin update public.organization_members set role='owner' where user_id=auth.uid(); raise exception 'Escalation allowed'; exception when insufficient_privilege then null; end; end $$;
do $$ begin begin insert into public.companies(organization_id,name,sector) values(current_setting('ambientis_test.org')::uuid,'Forbidden','other'); raise exception 'Client insert allowed'; exception when insufficient_privilege then null; end; end $$;
reset role;
select set_config('request.jwt.claims','{"sub":"f0000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
set local role authenticated;
select pg_temp.assert_true((select count(*)=0 from public.companies),'other consultancy isolation');
select set_config('ambientis_test.other_org',public.bootstrap_organization('Second synthetic consultancy')::text,true);
do $$ begin begin insert into public.facilities(organization_id,company_id,name,sector,state,city) values(current_setting('ambientis_test.other_org')::uuid,'f1000000-0000-4000-8000-000000000001','Cross tenant','gases','GO','Goiânia'); raise exception 'Cross-tenant FK accepted'; exception when foreign_key_violation then null; end; end $$;
reset role;
update public.organization_members set active=false where user_id='f0000000-0000-4000-8000-000000000003';
select set_config('request.jwt.claims','{"sub":"f0000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
set local role authenticated;
select pg_temp.assert_true((select count(*)=0 from public.companies),'live revocation');
reset role;
set local role anon;
do $$ begin begin perform * from public.companies; raise exception 'Anonymous read allowed'; exception when insufficient_privilege then null; end; end $$;
reset role;
select 'PASS: isolation, sharing, grants, revocation, cross-tenant integrity; all test data rolled back' as result;
rollback;
